(function(){const e=document.querySelector("[data-engagement-date-window]");if(!e)return;const n=Array.from(e.querySelectorAll('input[type="date"]')),r=e.querySelector("[data-engagement-date-apply]");if(!r||n.length!==2)return;const d=n.map(function(a){return a.value});function t(){r.classList.toggle("engagement-apply-reminder",n.some(function(a,i){return a.value!==d[i]}))}e.addEventListener("input",t),e.addEventListener("change",t),window.addEventListener("pageshow",t)})();
